import openNext from "./.open-next/worker.js";

type Env = { NEXT_PUBLIC_SITE_URL: string; CRON_SECRET: string; [k: string]: unknown };

export default {
  fetch: openNext.fetch,

  /** Daily Cron Trigger: calls the guarded expiry route through this same worker (no public round trip). */
  async scheduled(controller: { cron: string }, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const req = new Request(`${env.NEXT_PUBLIC_SITE_URL}/api/cron/expire`, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(
      openNext.fetch(req, env, ctx).then(async (res: Response) => {
        console.log(`cron ${controller.cron} -> ${res.status} ${await res.text()}`);
        if (!res.ok) throw new Error(`expiry cron failed: ${res.status}`);
      }),
    );
  },
};

// Durable Object classes OpenNext may re-export (none used with the KV cache).
